package com.ssafy.yumyumcoach.manager;

import com.ssafy.yumyumcoach.domain.User;
import com.ssafy.yumyumcoach.repository.DataRepository;
import java.util.*;
public class UserManager { private final DataRepository repo; public UserManager(DataRepository r){repo=r;} public User register(String id,String pw,String name,int age,String gender,double h,double w,String disease,String goal){if(repo.user(id).isPresent())throw new IllegalArgumentException("이미 사용 중인 아이디입니다.");if(pw.length()<4)throw new IllegalArgumentException("비밀번호는 4자 이상이어야 합니다.");User u=new User(id,pw,name,age,gender,h,w,disease,goal);repo.saveUser(u);return u;} public List<User> activeUsers(){return repo.users().stream().filter(User::isActive).toList();} public void update(User u,String name,int age,String gender,double h,double w,String disease,String goal){u.update(name,age,gender,h,w,disease,goal);repo.saveUser(u);} public void deactivate(User u){u.deactivate();repo.saveUser(u);} public void follow(User me,String target){User t=repo.user(target).filter(User::isActive).orElseThrow(()->new IllegalArgumentException("대상 회원이 없습니다."));if(me.getId().equals(t.getId()))throw new IllegalArgumentException("자기 자신은 팔로우할 수 없습니다.");me.getFollowing().add(target);repo.saveUser(me);} public void unfollow(User me,String target){if(!me.getFollowing().remove(target))throw new IllegalArgumentException("팔로우 중인 회원이 아닙니다.");repo.saveUser(me);} public List<User> following(User me){return me.getFollowing().stream().map(repo::user).flatMap(Optional::stream).filter(User::isActive).toList();} }
